// Package sbxerr writes the error responses generated by the gateway itself.
// Every such response carries an Sbx-Error header, so clients can tell a
// gateway error from an answer of the application behind it.
package sbxerr

import (
	"encoding/json"
	"html/template"
	"net/http"
	"strconv"
	"strings"
)

// Error codes of the Sbx-Error header (spec section 7.6).
const (
	CodeRouteNotFound          = "route_not_found"
	CodeRouteBlocked           = "route_blocked"
	CodeAuthRequired           = "auth_required"
	CodeTokenInvalid           = "token_invalid"
	CodeRateLimited            = "rate_limited"
	CodeAppNotListening        = "app_not_listening"
	CodeUpstreamError          = "upstream_error"
	CodeSandboxStarting        = "sandbox_starting"
	CodeSandboxStopped         = "sandbox_stopped"
	CodeSandboxUnavailable     = "sandbox_unavailable"
	CodeAgentUnavailable       = "agent_unavailable"
	CodeRouteLookupUnavailable = "route_lookup_unavailable"
	CodeOverloaded             = "overloaded"
	CodeAppTimeout             = "app_timeout"
)

// Error describes one gateway-generated response.
type Error struct {
	Status     int
	Code       string
	Message    string // short text for people; no internal details
	Retryable  bool
	RetryAfter int // seconds; the Retry-After header is set when > 0
	RequestID  string
	Refresh    bool // HTML only: reload the page every 5 seconds
}

// defaultMessages is used when Error.Message is empty.
var defaultMessages = map[string]string{
	CodeRouteNotFound:          "This address does not exist.",
	CodeRouteBlocked:           "This address is blocked.",
	CodeAuthRequired:           "Authentication is required.",
	CodeTokenInvalid:           "The access token is not valid.",
	CodeRateLimited:            "Too many requests. Try again later.",
	CodeAppNotListening:        "Nothing is listening on this port.",
	CodeUpstreamError:          "The application closed the connection or sent an invalid response.",
	CodeSandboxStarting:        "The sandbox is starting.",
	CodeSandboxStopped:         "The sandbox is stopped.",
	CodeSandboxUnavailable:     "The sandbox is not available.",
	CodeAgentUnavailable:       "The sandbox is not reachable yet.",
	CodeRouteLookupUnavailable: "The service is temporarily unavailable.",
	CodeOverloaded:             "The service is overloaded. Try again later.",
	CodeAppTimeout:             "The application did not answer in time.",
}

const fallbackMessage = "The request could not be completed."

var page = template.Must(template.New("page").Parse(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
{{if .Refresh}}<meta http-equiv="refresh" content="5">
{{end}}<title>{{.Status}} {{.Title}}</title>
<style>
body{font-family:system-ui,sans-serif;margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f6f7f9;color:#1c1f24}
main{max-width:32rem;padding:2rem}
h1{font-size:1.25rem;margin:0 0 .75rem}
p{margin:.5rem 0;line-height:1.5}
small{color:#6b7280}
@media (prefers-color-scheme:dark){body{background:#14161a;color:#e5e7eb}small{color:#9ca3af}}
</style>
</head>
<body>
<main>
<h1>{{.Status}} {{.Title}}</h1>
<p>{{.Message}}</p>
{{if .Refresh}}<p><small>This page reloads automatically.</small></p>
{{end}}{{if .RequestID}}<p><small>Request ID: {{.RequestID}}</small></p>
{{end}}</main>
</body>
</html>
`))

type pageData struct {
	Status    int
	Title     string
	Message   string
	RequestID string
	Refresh   bool
}

type jsonBody struct {
	Error jsonError `json:"error"`
}

type jsonError struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	Retryable bool   `json:"retryable"`
	RequestID string `json:"requestId"`
}

// Write sends e as an HTML page when the request accepts text/html and as JSON
// otherwise. r may be nil, which selects JSON.
func Write(w http.ResponseWriter, r *http.Request, e Error) {
	if e.Status == 0 {
		e.Status = http.StatusInternalServerError
	}
	if e.Message == "" {
		e.Message = defaultMessages[e.Code]
		if e.Message == "" {
			e.Message = fallbackMessage
		}
	}

	h := w.Header()
	h.Set("Sbx-Error", e.Code)
	h.Set("Cache-Control", "no-store")
	h.Set("X-Robots-Tag", "noindex, nofollow")
	h.Set("X-Content-Type-Options", "nosniff")
	h.Add("Vary", "Accept")
	if e.RetryAfter > 0 {
		h.Set("Retry-After", strconv.Itoa(e.RetryAfter))
	}

	html := r != nil && strings.Contains(strings.ToLower(r.Header.Get("Accept")), "text/html")
	head := r != nil && r.Method == http.MethodHead

	if html {
		h.Set("Content-Type", "text/html; charset=utf-8")
		w.WriteHeader(e.Status)
		if head {
			return
		}
		_ = page.Execute(w, pageData{
			Status:    e.Status,
			Title:     http.StatusText(e.Status),
			Message:   e.Message,
			RequestID: e.RequestID,
			Refresh:   e.Refresh,
		})
		return
	}

	h.Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(e.Status)
	if head {
		return
	}
	_ = json.NewEncoder(w).Encode(jsonBody{Error: jsonError{
		Code:      e.Code,
		Message:   e.Message,
		Retryable: e.Retryable,
		RequestID: e.RequestID,
	}})
}
